import { useCallback, useEffect, useRef, useState } from 'react';
import {
  Calculator, Check, CircleAlert, Github, LoaderCircle, MonitorPlay,
  Radio, Search, ShieldCheck, Usb, Video, VolumeX, Zap,
} from 'lucide-react';
import { startPlayerCapture, samplePlayerFrame } from './lib/capture.js';
import {
  catalogDonePacket, catalogErrorPacket, catalogItemPacket, catalogResetPacket,
  loadThumbnailPacked, parseCalculatorControl,
} from './lib/catalogProtocol.js';
import { FrameEncoder, framesEqual, renderPackedFrame } from './lib/frameEncoder.js';
import { CasioSerialTransport } from './lib/serialTransport.js';
import { CYT } from './lib/cytProtocol.js';
import { createYouTubePlayer } from './lib/youtube.js';

const DEFAULT_STATS = Object.freeze({ fps: 0, kbps: 0, sent: 0, dropped: 0, bytes: 0 });

function formatNumber(value, digits = 1) {
  return new Intl.NumberFormat('es-ES', { maximumFractionDigits: digits }).format(value);
}

function formatDuration(seconds) {
  const value = Math.max(0, Number(seconds) || 0);
  const hours = Math.floor(value / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  const rest = value % 60;
  return hours ? `${hours}:${String(minutes).padStart(2, '0')}:${String(rest).padStart(2, '0')}` : `${minutes}:${String(rest).padStart(2, '0')}`;
}

function Logo() {
  return (
    <span className="brand" aria-label="CasioYT">
      <span className="brand-icon" aria-hidden="true"><Calculator size={19} strokeWidth={1.8} /></span>
      <span>Casio<span>YT</span></span>
    </span>
  );
}

function Step({ number, title, children, complete, active }) {
  return (
    <li className={`step${complete ? ' is-complete' : ''}${active ? ' is-active' : ''}`}>
      <span className="step-index">{complete ? <Check size={14} strokeWidth={2.6} /> : number}</span>
      <span><strong>{title}</strong><small>{children}</small></span>
    </li>
  );
}

function StatusLine({ status, detail }) {
  const loading = status === 'connecting' || status === 'waiting';
  const ready = status === 'ready' || status === 'live' || status === 'connected';
  const title = status === 'live' ? 'Transmitiendo a la Casio'
    : status === 'ready' ? 'Calculadora preparada'
      : status === 'connected' || status === 'waiting' ? 'ESP32 conectada'
        : status === 'error' ? 'Revisa la conexión' : 'Sin conectar';
  return (
    <div className={`status-line status-${status}`} aria-live="polite">
      <span className="status-dot" aria-hidden="true">{loading ? <LoaderCircle size={14} /> : ready ? <Check size={12} /> : null}</span>
      <span><strong>{title}</strong><small>{detail}</small></span>
    </div>
  );
}

function TechItem({ icon: Icon, value, label }) {
  return <div className="tech-item"><Icon size={20} strokeWidth={1.65} /><span><strong>{value}</strong><small>{label}</small></span></div>;
}

function CalculatorPreview({ canvasRef, hasFrame }) {
  return (
    <div className="calculator-preview" aria-label="Previsualización del vídeo en la Casio fx-CG50">
      <img src={`${import.meta.env.BASE_URL}assets/fx-cg50-player.png`} alt="Parte superior de una calculadora Casio fx-CG50" />
      <canvas ref={canvasRef} className={hasFrame ? 'has-frame' : ''} width="384" height="216" />
    </div>
  );
}

function SearchMirror({ query, results, phase }) {
  if (!query && !results.length) {
    return (
      <div className="search-mirror-empty">
        <Search size={22} strokeWidth={1.6} />
        <span><strong>La búsqueda se escribe en la calculadora</strong><small>Abre CasioYT y usa su teclado. Esta página solo hace de puente.</small></span>
      </div>
    );
  }
  return (
    <div className="search-mirror">
      <div className="search-mirror-head">
        <span><Search size={16} /> <strong>{query || 'Buscando…'}</strong></span>
        <small>{phase === 'searching' ? 'Consultando YouTube…' : `${results.length} resultados enviados`}</small>
      </div>
      {results.length ? (
        <div className="browser-results">
          {results.map((item) => (
            <article className="browser-result" key={item.videoId}>
              <div className="browser-thumb">
                <img src={`/api/casioyt-thumbnail?id=${encodeURIComponent(item.videoId)}`} alt="" />
                <span>{formatDuration(item.durationSeconds)}</span>
              </div>
              <div><strong>{item.title}</strong><small>{item.channel}</small></div>
            </article>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export default function App() {
  const [videoId, setVideoId] = useState(null);
  const [playerReady, setPlayerReady] = useState(false);
  const [playerPlaying, setPlayerPlaying] = useState(false);
  const [deviceStatus, setDeviceStatus] = useState('disconnected');
  const [deviceDetail, setDeviceDetail] = useState('Conecta la XIAO ESP32-C3 por USB para continuar.');
  const [captureState, setCaptureState] = useState('idle');
  const [streamState, setStreamState] = useState('idle');
  const [bridgePhase, setBridgePhase] = useState('setup');
  const [bridgeError, setBridgeError] = useState('');
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [currentVideo, setCurrentVideo] = useState(null);
  const [stats, setStats] = useState(DEFAULT_STATS);
  const [hasPreview, setHasPreview] = useState(false);

  const playerMountRef = useRef(null);
  const playerCaptureRef = useRef(null);
  const playerRef = useRef(null);
  const playerCreatingRef = useRef(false);
  const transportRef = useRef(null);
  const probeControllerRef = useRef(null);
  const captureRef = useRef(null);
  const searchControllerRef = useRef(null);
  const sampleCanvasRef = useRef(document.createElement('canvas'));
  const previewCanvasRef = useRef(null);
  const encoderRef = useRef(new FrameEncoder());
  const streamingRef = useRef(false);
  const animationRef = useRef(0);
  const lastSampleAtRef = useRef(0);
  const lastPackedRef = useRef(null);
  const statsRef = useRef({ ...DEFAULT_STATS, startedAt: 0, lastRenderedAt: 0, lastSentAt: 0 });
  const consecutiveErrorsRef = useRef(0);
  const controlHandlerRef = useRef(null);
  const resultsRef = useRef([]);
  const resultsGenerationRef = useRef(0);
  const catalogSequenceRef = useRef(40000);

  const serialSupported = CasioSerialTransport.supported();
  const captureSupported = Boolean(navigator.mediaDevices?.getDisplayMedia);
  const calculatorReady = deviceStatus === 'ready' || deviceStatus === 'live';
  const captureReady = captureState === 'ready' || captureState === 'live';

  const nextCatalogSequence = useCallback(() => {
    catalogSequenceRef.current = (catalogSequenceRef.current + 1) & 0xffff;
    if (!catalogSequenceRef.current) catalogSequenceRef.current = 40000;
    return catalogSequenceRef.current;
  }, []);

  const announceBridge = useCallback(async () => {
    const transport = transportRef.current;
    if (!transport?.videoReady) return;
    try { await transport.sendControl(CYT.CONTROL_BRIDGE, captureRef.current ? 1 : 0); }
    catch { /* The calculator heartbeat will recover the link. */ }
  }, []);

  const stopFramePump = useCallback((reason = '') => {
    streamingRef.current = false;
    window.cancelAnimationFrame(animationRef.current);
    encoderRef.current.reset();
    lastPackedRef.current = null;
    setStreamState(captureRef.current ? 'ready' : 'idle');
    setCaptureState(captureRef.current ? 'ready' : 'idle');
    setDeviceStatus((status) => status === 'live' ? 'ready' : status);
    if (reason) setBridgeError(reason);
  }, []);

  const controlPlayer = useCallback((operation, value) => {
    const player = playerRef.current;
    if (!player || operation !== CYT.CONTROL_KEYS) return;
    if (value & 1) player.seekTo(Math.max(0, player.getCurrentTime() - 5), true);
    if (value & 2) player.seekTo(player.getCurrentTime() + 5, true);
    if (value & 16) {
      if (player.getPlayerState() === window.YT?.PlayerState?.PLAYING) player.pauseVideo();
      else player.playVideo();
    }
  }, []);

  const pumpFrames = useCallback(async () => {
    if (!streamingRef.current || !captureRef.current || !transportRef.current) return;
    const now = performance.now();
    if (now - lastSampleAtRef.current < 125) {
      animationRef.current = window.requestAnimationFrame(pumpFrames);
      return;
    }
    lastSampleAtRef.current = now;
    try {
      const packed = samplePlayerFrame(captureRef.current, playerCaptureRef.current, sampleCanvasRef.current);
      renderPackedFrame(previewCanvasRef.current, packed);
      setHasPreview(true);
      if (framesEqual(packed, lastPackedRef.current) && now - statsRef.current.lastSentAt < 1000) {
        animationRef.current = window.requestAnimationFrame(pumpFrames);
        return;
      }
      const encoded = encoderRef.current.encode(packed);
      await transportRef.current.sendFrame(encoded);
      encoderRef.current.commit(encoded);
      lastPackedRef.current = packed;
      consecutiveErrorsRef.current = 0;
      const tracker = statsRef.current;
      tracker.sent += 1;
      tracker.bytes += encoded.packet.length;
      tracker.lastSentAt = performance.now();
      const elapsed = Math.max(1, tracker.lastSentAt - tracker.startedAt);
      if (tracker.lastSentAt - tracker.lastRenderedAt > 450) {
        tracker.lastRenderedAt = tracker.lastSentAt;
        setStats({ fps: tracker.sent * 1000 / elapsed, kbps: tracker.bytes * 8 / elapsed, sent: tracker.sent, dropped: tracker.dropped, bytes: tracker.bytes });
      }
    } catch (error) {
      statsRef.current.dropped += 1;
      consecutiveErrorsRef.current += 1;
      encoderRef.current.forceKeyframe();
      if (consecutiveErrorsRef.current >= 3) {
        stopFramePump(`La transmisión se ha detenido: ${error.message}`);
        setDeviceStatus('waiting');
        setDeviceDetail('Vuelve a abrir CasioYT en la calculadora y espera a que el enlace se recupere.');
        return;
      }
    }
    animationRef.current = window.requestAnimationFrame(pumpFrames);
  }, [stopFramePump]);

  const startFramePump = useCallback(() => {
    if (!captureRef.current || !transportRef.current?.videoReady) throw new Error('Activa primero la captura de esta pestaña.');
    encoderRef.current.reset();
    lastPackedRef.current = null;
    statsRef.current = { ...DEFAULT_STATS, startedAt: performance.now(), lastRenderedAt: 0, lastSentAt: 0 };
    setStats(DEFAULT_STATS);
    consecutiveErrorsRef.current = 0;
    streamingRef.current = true;
    setStreamState('live');
    setCaptureState('live');
    setDeviceStatus('live');
    setDeviceDetail('YouTube responde a las teclas de la calculadora y envía vídeo en tiempo real.');
    setBridgePhase('streaming');
    lastSampleAtRef.current = 0;
    animationRef.current = window.requestAnimationFrame(pumpFrames);
  }, [pumpFrames]);

  const ensurePlayer = useCallback(async (id) => {
    if (playerRef.current) {
      playerRef.current.loadVideoById(id);
      setPlayerReady(true);
      return playerRef.current;
    }
    if (playerCreatingRef.current) throw new Error('El reproductor todavía se está preparando.');
    playerCreatingRef.current = true;
    try {
      const player = await createYouTubePlayer(playerMountRef.current, id, (event) => {
        setPlayerPlaying(event.data === window.YT?.PlayerState?.PLAYING);
        if (event.data === window.YT?.PlayerState?.ENDED) stopFramePump();
      }, (error) => {
        stopFramePump(error.message);
        setBridgePhase('error');
      });
      playerRef.current = player;
      setPlayerReady(true);
      return player;
    } finally { playerCreatingRef.current = false; }
  }, [stopFramePump]);

  const sendCatalogError = useCallback(async (generation, message) => {
    const transport = transportRef.current;
    if (!transport?.videoReady) return;
    await transport.sendCheckedPacket(catalogErrorPacket(nextCatalogSequence(), generation, message));
  }, [nextCatalogSequence]);

  const handleSearch = useCallback(async ({ generation, query: requestedQuery }) => {
    const cleanQuery = requestedQuery.trim();
    if (!cleanQuery) {
      await sendCatalogError(generation, 'Escribe algo para buscar en YouTube.');
      return;
    }
    searchControllerRef.current?.abort();
    const controller = new AbortController();
    searchControllerRef.current = controller;
    stopFramePump();
    playerRef.current?.pauseVideo?.();
    setQuery(cleanQuery);
    setResults([]);
    resultsRef.current = [];
    resultsGenerationRef.current = generation;
    setCurrentVideo(null);
    setBridgeError('');
    setBridgePhase('searching');
    try {
      const response = await fetch(`/api/casioyt-search?q=${encodeURIComponent(cleanQuery)}`, { signal: controller.signal });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(body.error || 'YouTube no ha podido completar la búsqueda.');
      const found = Array.isArray(body.items) ? body.items.slice(0, CYT.SEARCH_RESULTS) : [];
      const transport = transportRef.current;
      if (!transport?.videoReady || controller.signal.aborted) return;
      await transport.sendCheckedPacket(catalogResetPacket(nextCatalogSequence(), generation, found.length));
      const thumbnails = await Promise.all(found.map((item) => loadThumbnailPacked(item.videoId).catch(() => new Uint8Array(CYT.THUMB_BYTES).fill(0x12))));
      for (let index = 0; index < found.length; index += 1) {
        if (controller.signal.aborted) return;
        await transport.sendCheckedPacket(catalogItemPacket(nextCatalogSequence(), generation, index, found[index], thumbnails[index]), 4500);
      }
      await transport.sendCheckedPacket(catalogDonePacket(nextCatalogSequence(), generation));
      resultsGenerationRef.current = generation;
      resultsRef.current = found;
      setResults(found);
      setBridgePhase('results');
    } catch (error) {
      if (error.name === 'AbortError') return;
      setBridgeError(error.message);
      setBridgePhase('error');
      try { await sendCatalogError(generation, error.message); } catch { /* The calculator may have closed. */ }
    }
  }, [nextCatalogSequence, sendCatalogError, stopFramePump]);

  const handleSelect = useCallback(async ({ generation, index, videoId: selectedId }) => {
    const item = resultsRef.current[index];
    if (generation !== resultsGenerationRef.current || !item || item.videoId !== selectedId) {
      await sendCatalogError(generation, 'El resultado ya no está disponible. Busca de nuevo.');
      return;
    }
    if (!captureRef.current) {
      await sendCatalogError(generation, 'Activa la captura de vídeo en la web de CasioYT.');
      return;
    }
    setBridgeError('');
    setBridgePhase('loading');
    setCurrentVideo(item);
    setVideoId(item.videoId);
    try {
      const player = await ensurePlayer(item.videoId);
      player.playVideo();
      startFramePump();
    } catch (error) {
      setBridgeError(error.message);
      setBridgePhase('error');
      await sendCatalogError(generation, 'No se pudo abrir este vídeo.');
    }
  }, [ensurePlayer, sendCatalogError, startFramePump]);

  const handleCalculatorControl = useCallback(async (detail) => {
    const control = parseCalculatorControl(detail.payload);
    if (!control) return;
    if (control.operation === CYT.CONTROL_KEYFRAME) { encoderRef.current.forceKeyframe(); return; }
    if (control.operation === CYT.CONTROL_KEYS) { controlPlayer(control.operation, control.value); return; }
    if (control.operation === CYT.CONTROL_SEARCH) { await handleSearch(control); return; }
    if (control.operation === CYT.CONTROL_SELECT) { await handleSelect(control); return; }
    if (control.operation === CYT.CONTROL_BACK) {
      stopFramePump();
      playerRef.current?.pauseVideo?.();
      setBridgePhase(resultsRef.current.length ? 'results' : 'ready');
      setCurrentVideo(null);
    }
  }, [controlPlayer, handleSearch, handleSelect, stopFramePump]);
  controlHandlerRef.current = handleCalculatorControl;

  const beginProbeLoop = useCallback(async (transport) => {
    probeControllerRef.current?.abort();
    const controller = new AbortController();
    probeControllerRef.current = controller;
    setDeviceStatus('waiting');
    setDeviceDetail('Abre CasioYT en la calculadora. La detectaremos automáticamente.');
    try {
      const ready = await transport.waitForCalculator({ attempts: 120, interval: 650, signal: controller.signal });
      if (!controller.signal.aborted && ready) {
        setDeviceStatus('ready');
        setDeviceDetail('Enlace preparado. Busca vídeos directamente desde la calculadora.');
        setBridgePhase('ready');
        await announceBridge();
      } else if (!controller.signal.aborted) {
        setDeviceStatus('connected');
        setDeviceDetail('La ESP32 responde, pero CasioYT todavía no está abierto en la calculadora.');
      }
    } catch (error) {
      if (error.name !== 'AbortError' && !controller.signal.aborted) {
        setDeviceStatus('error');
        setDeviceDetail(error.message);
      }
    }
  }, [announceBridge]);

  const handleConnect = useCallback(async () => {
    setBridgeError('');
    if (!serialSupported) {
      setDeviceStatus('error');
      setDeviceDetail('Utiliza Chrome o Edge de escritorio para acceder a Web Serial.');
      return;
    }
    if (transportRef.current?.connected) { beginProbeLoop(transportRef.current); return; }
    setDeviceStatus('connecting');
    setDeviceDetail('Selecciona la XIAO ESP32-C3…');
    const transport = new CasioSerialTransport();
    transportRef.current = transport;
    transport.addEventListener('control', (event) => { void controlHandlerRef.current?.(event.detail); });
    transport.addEventListener('state', (event) => {
      if (!event.detail.connected) {
        stopFramePump(event.detail.error || 'La ESP32 se ha desconectado.');
        setDeviceStatus('disconnected');
        setDeviceDetail('Conecta la XIAO ESP32-C3 por USB para continuar.');
      }
    });
    try {
      await transport.connect();
      await beginProbeLoop(transport);
    } catch (error) {
      setDeviceStatus(error.name === 'NotFoundError' ? 'disconnected' : 'error');
      setDeviceDetail(error.name === 'NotFoundError' ? 'No se seleccionó ningún dispositivo.' : error.message || 'No se pudo abrir el puerto USB.');
    }
  }, [beginProbeLoop, serialSupported, stopFramePump]);

  const handleEnableCapture = useCallback(async () => {
    setBridgeError('');
    if (!captureSupported) {
      setBridgeError('Este navegador no permite capturar la pestaña. Utiliza Chrome o Edge de escritorio.');
      return;
    }
    setCaptureState('capturing');
    try {
      captureRef.current?.stop();
      const capture = await startPlayerCapture(playerCaptureRef.current);
      captureRef.current = capture;
      capture.track.addEventListener('ended', () => {
        stopFramePump('La captura de la pestaña se ha detenido.');
        captureRef.current = null;
        setCaptureState('idle');
        void announceBridge();
      });
      setCaptureState('ready');
      setStreamState('ready');
      await announceBridge();
    } catch (error) {
      setCaptureState('idle');
      setBridgeError(error.name === 'NotAllowedError' ? 'Selecciona esta misma pestaña cuando Chrome pregunte qué quieres compartir.' : error.message || 'No se pudo compartir la pestaña.');
    }
  }, [announceBridge, captureSupported, stopFramePump]);

  useEffect(() => () => {
    probeControllerRef.current?.abort();
    searchControllerRef.current?.abort();
    streamingRef.current = false;
    window.cancelAnimationFrame(animationRef.current);
    captureRef.current?.stop();
    playerRef.current?.destroy?.();
    transportRef.current?.close();
  }, []);

  useEffect(() => {
    const timer = window.setInterval(() => { void announceBridge(); }, 2000);
    return () => window.clearInterval(timer);
  }, [announceBridge]);

  const stageOne = deviceStatus !== 'disconnected' && deviceStatus !== 'error';
  const stageTwo = calculatorReady;
  const stageThree = captureReady;

  return (
    <div className="app-shell">
      <header className="topbar">
        <a href="/tools/casio/" className="brand-link"><Logo /></a>
        <nav aria-label="Navegación principal">
          <a href="/tools/casio/">Proyectos Casio</a>
          <a href="https://github.com/samilososami/CasioYT" target="_blank" rel="noreferrer"><Github size={17} /> GitHub</a>
        </nav>
        <span className="header-note">Busca, elige y reproduce desde la calculadora.</span>
      </header>

      <main className="workspace">
        <section className="source-column">
          <div className="intro">
            <h1>YouTube, desde tu Casio.</h1>
            <p>Escribe la búsqueda en la calculadora, recorre los resultados y pulsa EXE. Sin copiar enlaces.</p>
          </div>

          <SearchMirror query={query} results={results} phase={bridgePhase} />

          <div className={`player-frame${videoId ? ' has-video' : ''}`} ref={playerCaptureRef}>
            <div ref={playerMountRef} id="casioyt-youtube-player" />
            {!videoId ? (
              <div className="player-empty">
                <span><Video size={31} strokeWidth={1.4} /></span>
                <strong>{bridgePhase === 'searching' ? 'Buscando en YouTube…' : 'Esperando una selección desde la Casio'}</strong>
                <small>El reproductor oficial se abrirá automáticamente al pulsar EXE.</small>
              </div>
            ) : null}
          </div>

          <div className="source-caption">
            <span><ShieldCheck size={16} /> La clave y la búsqueda viven en el servidor; el vídeo se procesa localmente.</span>
            <span>{playerPlaying ? <><span className="live-pip" /> Reproduciendo</> : currentVideo ? currentVideo.title : playerReady ? 'Reproductor preparado' : 'Esperando a la calculadora'}</span>
          </div>
        </section>

        <aside className="control-rail">
          <div className="rail-heading">
            <Search size={22} strokeWidth={1.7} />
            <span><h2>Preparar CasioYT</h2><p>Dos permisos en el navegador; después todo se controla desde la calculadora.</p></span>
          </div>

          <ol className="steps">
            <Step number="1" title="Conecta la ESP32" complete={stageOne} active={!stageOne}>Autoriza su puerto USB en Chrome.</Step>
            <Step number="2" title="Abre CasioYT" complete={stageTwo} active={stageOne && !stageTwo}>Inicia el add-in en tu fx-CG50.</Step>
            <Step number="3" title="Activa el vídeo" complete={stageThree} active={stageTwo && !stageThree}>Comparte esta misma pestaña una sola vez.</Step>
          </ol>

          <div className="action-row">
            <button className="primary-button" type="button" onClick={handleConnect} disabled={deviceStatus === 'connecting'}>
              {deviceStatus === 'connecting' ? <LoaderCircle className="spin" size={17} /> : <Usb size={17} />} {stageOne ? 'Comprobar enlace' : 'Conectar ESP32'}
            </button>
            <button className="stream-button" type="button" onClick={handleEnableCapture} disabled={!stageOne || captureState === 'capturing' || stageThree}>
              {captureState === 'capturing' ? <LoaderCircle className="spin" size={17} /> : stageThree ? <Check size={16} /> : <MonitorPlay size={16} />} {stageThree ? 'Vídeo activado' : 'Activar vídeo'}
            </button>
          </div>

          <StatusLine status={deviceStatus} detail={deviceDetail} />
          {bridgeError ? <p className="stream-error"><CircleAlert size={15} /> {bridgeError}</p> : null}

          <section className="technical" aria-labelledby="technical-title">
            <div className="section-title"><span><Radio size={19} /><strong id="technical-title">Estado técnico</strong></span><small>{streamState === 'live' ? `${formatNumber(stats.fps)} FPS · ${formatNumber(stats.kbps)} kbit/s` : bridgePhase === 'searching' ? 'Buscando desde la Casio…' : 'Puente preparado.'}</small></div>
            <div className="tech-grid">
              <TechItem icon={MonitorPlay} value="128 × 72" label="Resolución Casio" />
              <TechItem icon={Zap} value="8 FPS" label="Objetivo de envío" />
              <TechItem icon={VolumeX} value="Sin audio" label="Solo vídeo" />
            </div>
          </section>

          <section className="preview-section" aria-labelledby="preview-title">
            <div className="section-title"><span><Calculator size={19} /><strong id="preview-title">Vista previa en la calculadora</strong></span><small>Simulación 384 × 216</small></div>
            <CalculatorPreview canvasRef={previewCanvasRef} hasFrame={hasPreview} />
            <div className="preview-meta"><span>{streamState === 'live' ? `${stats.sent} frames confirmados` : 'Aparecerá al reproducir un vídeo'}</span>{stats.dropped ? <span>{stats.dropped} descartados</span> : null}</div>
          </section>
        </aside>
      </main>

      <footer className="footer">
        <span><ShieldCheck size={16} /> YouTube Data API para buscar; reproductor oficial para reproducir.</span>
        <a href="https://samilososami.com">samilososami.com</a>
      </footer>
    </div>
  );
}
