import {
  CYT,
  CytParser,
  packPacket,
  packWireCommand,
  parseWireLine,
} from './cytProtocol.js';

const ESPRESSIF_USB_VENDOR_ID = 0x303a;

function wait(milliseconds) {
  return new Promise((resolve) => window.setTimeout(resolve, milliseconds));
}

function randomId() {
  const value = new Uint32Array(1);
  crypto.getRandomValues(value);
  return value[0] & 0x7fffffff;
}

export class CasioSerialTransport extends EventTarget {
  port = null;
  connected = false;
  videoReady = false;

  #reader = null;
  #writer = null;
  #readTask = null;
  #parser = new CytParser();
  #asciiLine = '';
  #writeChain = Promise.resolve();
  #pendingAcks = new Map();
  #pendingPings = new Map();
  #pendingHealth = new Map();
  #disconnectHandler = null;

  static supported() {
    return typeof navigator !== 'undefined' && 'serial' in navigator;
  }

  async connect() {
    if (!CasioSerialTransport.supported()) throw new Error('Web Serial no está disponible en este navegador');
    if (this.connected) return;

    this.port = await navigator.serial.requestPort({
      filters: [{ usbVendorId: ESPRESSIF_USB_VENDOR_ID }],
    });
    await this.port.open({ baudRate: 115200, bufferSize: 65536 });
    this.#reader = this.port.readable.getReader();
    this.#writer = this.port.writable.getWriter();
    this.connected = true;
    this.#parser.reset();
    this.#asciiLine = '';
    this.#readTask = this.#readLoop();
    this.#disconnectHandler = (event) => {
      if (event.target === this.port || event.port === this.port) this.#handleDisconnect('La ESP32 se ha desconectado');
    };
    navigator.serial.addEventListener('disconnect', this.#disconnectHandler);
    this.dispatchEvent(new CustomEvent('state', { detail: { connected: true, videoReady: false } }));
  }

  async #readLoop() {
    try {
      while (this.connected && this.#reader) {
        const { value, done } = await this.#reader.read();
        if (done) break;
        if (!value?.length) continue;
        this.#feedAscii(value);
        for (const packet of this.#parser.feed(value)) this.#handlePacket(packet);
      }
    } catch (error) {
      if (this.connected) this.#handleDisconnect(error?.message || 'Se perdió el puerto serie');
    }
  }

  #feedAscii(bytes) {
    for (const byte of bytes) {
      if (byte === 10) {
        const payload = parseWireLine(this.#asciiLine);
        this.#asciiLine = '';
        if (!payload) continue;
        const fields = payload.split(':');
        if (fields[0] === 'YT_HEALTH' && fields.length >= 7) {
          const id = Number(fields[1]);
          const pending = this.#pendingHealth.get(id);
          if (pending) {
            this.#pendingHealth.delete(id);
            pending.resolve({
              protocol: Number(fields[2]),
              baudRate: Number(fields[3]),
              width: Number(fields[4]),
              height: Number(fields[5]),
              exclusive: fields[6] === '1',
            });
          }
        }
        continue;
      }
      if (byte === 13) continue;
      if (byte >= 32 && byte <= 126) {
        this.#asciiLine += String.fromCharCode(byte);
        if (this.#asciiLine.length > 260) this.#asciiLine = this.#asciiLine.slice(-128);
      } else if (this.#asciiLine.length && !this.#asciiLine.includes('@@@')) {
        this.#asciiLine = '';
      }
    }
  }

  #handlePacket(packet) {
    if (packet.type === CYT.TYPE_STATUS && packet.payload.length >= 3) {
      const status = packet.payload[0];
      const relatedSequence = packet.payload[1] | (packet.payload[2] << 8);
      const pending = this.#pendingAcks.get(relatedSequence);
      if (pending && status === CYT.STATUS_ACK) {
        this.#pendingAcks.delete(relatedSequence);
        pending.resolve();
      } else if (pending && (status === CYT.STATUS_BUSY || status === CYT.STATUS_BAD_FRAME)) {
        this.#pendingAcks.delete(relatedSequence);
        pending.reject(new Error(status === CYT.STATUS_BUSY ? 'La ESP32 está ocupada' : 'La calculadora rechazó el frame'));
      }
      this.dispatchEvent(new CustomEvent('status', { detail: { status, relatedSequence } }));
      return;
    }

    if (packet.type === CYT.TYPE_CONTROL && packet.payload.length) {
      if (packet.payload[0] === CYT.CONTROL_PING) {
        const pending = this.#pendingPings.get(packet.sequence);
        if (pending) {
          this.#pendingPings.delete(packet.sequence);
          pending.resolve(true);
        }
      }
      this.dispatchEvent(new CustomEvent('control', {
        detail: {
          operation: packet.payload[0],
          value: packet.payload[1] ?? 0,
          sequence: packet.sequence,
          payload: packet.payload.slice(),
        },
      }));
    }
  }

  async #write(bytes) {
    if (!this.connected || !this.#writer) throw new Error('La ESP32 no está conectada');
    this.#writeChain = this.#writeChain.then(() => this.#writer.write(bytes));
    return this.#writeChain;
  }

  async #withTimeout(map, key, bytes, timeoutMs) {
    let timer;
    const response = new Promise((resolve, reject) => {
      timer = window.setTimeout(() => {
        map.delete(key);
        reject(new Error('La ESP32 no ha confirmado la operación'));
      }, timeoutMs);
      map.set(key, {
        resolve: (value) => {
          window.clearTimeout(timer);
          resolve(value);
        },
        reject: (error) => {
          window.clearTimeout(timer);
          reject(error);
        },
      });
    });
    await this.#write(bytes);
    return response;
  }

  async probe() {
    if (!this.connected) return 'disconnected';

    const healthId = randomId();
    try {
      const health = await this.#withTimeout(
        this.#pendingHealth,
        healthId,
        packWireCommand(`YT_HEALTH:${healthId}`),
        480,
      );
      if (health.protocol !== 1 || health.baudRate !== 115200 || health.width !== 128 || health.height !== 72) {
        throw new Error('El firmware de la ESP32 no es compatible con CasioYT');
      }
      this.videoReady = health.exclusive;
      return health.exclusive ? 'video' : 'legacy';
    } catch (error) {
      if (error.message.includes('no es compatible')) throw error;
    }

    const sequence = randomId() & 0xffff || 1;
    const ping = packPacket(CYT.TYPE_CONTROL, 0, sequence, new Uint8Array([CYT.CONTROL_PING]));
    try {
      await this.#withTimeout(this.#pendingPings, sequence, ping, 620);
      this.videoReady = true;
      this.dispatchEvent(new CustomEvent('state', { detail: { connected: true, videoReady: true } }));
      return 'video';
    } catch {
      this.videoReady = false;
      return 'unknown';
    }
  }

  async waitForCalculator({ attempts = 20, interval = 650, signal } = {}) {
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      if (signal?.aborted) throw new DOMException('Cancelado', 'AbortError');
      const state = await this.probe();
      this.dispatchEvent(new CustomEvent('probe', { detail: { state, attempt: attempt + 1, attempts } }));
      if (state === 'video') return true;
      await wait(interval);
    }
    return false;
  }

  async sendFrame(encoded, timeoutMs = 2400) {
    if (!this.videoReady) throw new Error('Abre CasioYT en la calculadora antes de transmitir');
    return this.#withTimeout(this.#pendingAcks, encoded.sequence, encoded.packet, timeoutMs);
  }

  async sendCheckedPacket(packet, timeoutMs = 3000) {
    if (!this.videoReady) throw new Error('Abre CasioYT en la calculadora antes de enviar datos');
    if (!(packet instanceof Uint8Array) || packet.length < CYT.HEADER_SIZE) {
      throw new TypeError('Paquete CasioYT inválido');
    }
    const sequence = packet[8] | (packet[9] << 8);
    return this.#withTimeout(this.#pendingAcks, sequence, packet, timeoutMs);
  }

  async sendControl(operation, value = 0) {
    if (!this.videoReady) throw new Error('Abre CasioYT en la calculadora antes de enviar controles');
    const sequence = randomId() & 0xffff || 1;
    return this.#write(packPacket(
      CYT.TYPE_CONTROL,
      0,
      sequence,
      new Uint8Array([operation & 0xff, value & 0xff]),
    ));
  }

  #rejectPending(message) {
    const error = new Error(message);
    for (const map of [this.#pendingAcks, this.#pendingPings, this.#pendingHealth]) {
      for (const pending of map.values()) pending.reject(error);
      map.clear();
    }
  }

  #handleDisconnect(message) {
    if (!this.connected) return;
    this.connected = false;
    this.videoReady = false;
    this.#rejectPending(message);
    this.dispatchEvent(new CustomEvent('state', { detail: { connected: false, videoReady: false, error: message } }));
  }

  async close() {
    this.connected = false;
    this.videoReady = false;
    this.#rejectPending('Puerto cerrado');
    if (this.#disconnectHandler && CasioSerialTransport.supported()) {
      navigator.serial.removeEventListener('disconnect', this.#disconnectHandler);
      this.#disconnectHandler = null;
    }
    try {
      await this.#reader?.cancel();
    } catch {
      // The device may already be gone.
    }
    try {
      this.#reader?.releaseLock();
    } catch {
      // Ignore an already released lock.
    }
    try {
      this.#writer?.releaseLock();
    } catch {
      // Ignore an already released lock.
    }
    try {
      await this.port?.close();
    } catch {
      // Closing a removed serial device can reject.
    }
    this.#reader = null;
    this.#writer = null;
    this.port = null;
    this.dispatchEvent(new CustomEvent('state', { detail: { connected: false, videoReady: false } }));
  }
}
