import { CYT, packPacket, rleEncode } from './cytProtocol.js';
import { quantizeRgbaToPacked } from './frameEncoder.js';

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function limitedUtf8(value, maximum) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  const bytes = encoder.encode(text);
  if (bytes.length <= maximum) return bytes;
  let end = maximum;
  while (end > 0 && (bytes[end] & 0xc0) === 0x80) end -= 1;
  return bytes.slice(0, end);
}

function generationBytes(generation) {
  return [generation & 0xff, (generation >>> 8) & 0xff];
}

export function parseCalculatorControl(payload) {
  if (!(payload instanceof Uint8Array) || !payload.length) return null;
  const operation = payload[0];
  if (operation === CYT.CONTROL_SEARCH && payload.length >= 4) {
    return {
      operation,
      generation: payload[1] | (payload[2] << 8),
      query: decoder.decode(payload.slice(3)).trim(),
    };
  }
  if (operation === CYT.CONTROL_SELECT && payload.length >= 15) {
    return {
      operation,
      generation: payload[1] | (payload[2] << 8),
      index: payload[3],
      videoId: decoder.decode(payload.slice(4, 15)),
    };
  }
  return { operation, value: payload[1] ?? 0 };
}

export function catalogResetPacket(sequence, generation, count) {
  return packPacket(CYT.TYPE_CATALOG, 0, sequence,
    new Uint8Array([CYT.CATALOG_RESET, ...generationBytes(generation), count & 0xff]));
}

export function catalogDonePacket(sequence, generation) {
  return packPacket(CYT.TYPE_CATALOG, 0, sequence,
    new Uint8Array([CYT.CATALOG_DONE, ...generationBytes(generation)]));
}

export function catalogErrorPacket(sequence, generation, message) {
  const text = limitedUtf8(message || 'No se pudo buscar en YouTube.', 80);
  const payload = new Uint8Array(3 + text.length);
  payload.set([CYT.CATALOG_ERROR, ...generationBytes(generation)], 0);
  payload.set(text, 3);
  return packPacket(CYT.TYPE_CATALOG, 0, sequence, payload);
}

export function catalogItemPacket(sequence, generation, index, item, thumbnailPacked) {
  if (!(thumbnailPacked instanceof Uint8Array) || thumbnailPacked.length !== CYT.THUMB_BYTES) {
    throw new RangeError('Miniatura CasioYT inválida');
  }
  const videoId = encoder.encode(item.videoId || '');
  if (videoId.length !== CYT.VIDEO_ID_SIZE) throw new RangeError('ID de YouTube inválido');
  const title = limitedUtf8(item.title, CYT.TITLE_MAX);
  const channel = limitedUtf8(item.channel, CYT.CHANNEL_MAX);
  const thumbnail = rleEncode(thumbnailPacked);
  const payload = new Uint8Array(21 + title.length + channel.length + thumbnail.length);
  const view = new DataView(payload.buffer);
  payload[0] = CYT.CATALOG_ITEM;
  payload[1] = generation & 0xff;
  payload[2] = (generation >>> 8) & 0xff;
  payload[3] = index & 0xff;
  view.setUint16(4, Math.min(0xffff, Number(item.durationSeconds) || 0), true);
  payload[6] = title.length;
  payload[7] = channel.length;
  payload.set(videoId, 8);
  view.setUint16(19, thumbnail.length, true);
  payload.set(title, 21);
  payload.set(channel, 21 + title.length);
  payload.set(thumbnail, 21 + title.length + channel.length);
  return packPacket(CYT.TYPE_CATALOG, 0, sequence, payload);
}

export async function loadThumbnailPacked(videoId, endpoint = '/api/casioyt-thumbnail') {
  const response = await fetch(`${endpoint}?id=${encodeURIComponent(videoId)}`);
  if (!response.ok) throw new Error('No se pudo cargar una miniatura de YouTube');
  const bitmap = await createImageBitmap(await response.blob());
  const canvas = document.createElement('canvas');
  canvas.width = CYT.THUMB_WIDTH;
  canvas.height = CYT.THUMB_HEIGHT;
  const context = canvas.getContext('2d', { alpha: false, colorSpace: 'srgb', willReadFrequently: true });
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = 'high';
  context.fillStyle = '#07090d';
  context.fillRect(0, 0, canvas.width, canvas.height);
  const scale = Math.max(canvas.width / bitmap.width, canvas.height / bitmap.height);
  const width = bitmap.width * scale;
  const height = bitmap.height * scale;
  context.drawImage(bitmap, (canvas.width - width) / 2, (canvas.height - height) / 2, width, height);
  bitmap.close?.();
  return quantizeRgbaToPacked(
    context.getImageData(0, 0, CYT.THUMB_WIDTH, CYT.THUMB_HEIGHT).data,
    CYT.THUMB_WIDTH,
    CYT.THUMB_HEIGHT,
  );
}
