let youtubeApiPromise;

export function parseYouTubeId(input) {
  const value = input.trim();
  if (/^[A-Za-z0-9_-]{11}$/.test(value)) return value;
  let url;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  const host = url.hostname.replace(/^www\./, '');
  if (host === 'youtu.be') return /^[A-Za-z0-9_-]{11}$/.test(url.pathname.slice(1).split('/')[0]) ? url.pathname.slice(1).split('/')[0] : null;
  if (!['youtube.com', 'm.youtube.com', 'music.youtube.com', 'youtube-nocookie.com'].includes(host)) return null;
  const candidate = url.searchParams.get('v') || url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})/)?.[1];
  return candidate && /^[A-Za-z0-9_-]{11}$/.test(candidate) ? candidate : null;
}

export function loadYouTubeApi() {
  if (window.YT?.Player) return Promise.resolve(window.YT);
  if (youtubeApiPromise) return youtubeApiPromise;
  youtubeApiPromise = new Promise((resolve, reject) => {
    const previous = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => {
      previous?.();
      resolve(window.YT);
    };
    const existing = document.querySelector('script[data-casioyt-youtube]');
    if (existing) return;
    const script = document.createElement('script');
    script.src = 'https://www.youtube.com/iframe_api';
    script.async = true;
    script.dataset.casioytYoutube = 'true';
    script.onerror = () => reject(new Error('No se pudo cargar el reproductor oficial de YouTube'));
    document.head.appendChild(script);
  });
  return youtubeApiPromise;
}

export function createYouTubePlayer(element, videoId, onStateChange, onError) {
  return loadYouTubeApi().then((YT) => new Promise((resolve, reject) => {
    let ready = false;
    const player = new YT.Player(element, {
      host: 'https://www.youtube-nocookie.com',
      width: '100%',
      height: '100%',
      videoId,
      playerVars: {
        playsinline: 1,
        rel: 0,
        modestbranding: 1,
        enablejsapi: 1,
        origin: window.location.origin,
      },
      events: {
        onReady: () => {
          ready = true;
          player.mute();
          resolve(player);
        },
        onStateChange,
        onError: (event) => {
          const error = new Error(`YouTube no puede reproducir este vídeo (código ${event.data}).`);
          if (!ready) reject(error);
          onError?.(error);
        },
      },
    });
  }));
}
