import { CYT, packPacket, rleEncode } from './cytProtocol.js';

export const CASIO_PALETTE = Object.freeze([
  [7, 9, 13],
  [25, 29, 36],
  [36, 46, 62],
  [28, 91, 181],
  [47, 125, 246],
  [70, 171, 242],
  [62, 193, 155],
  [105, 207, 116],
  [238, 194, 74],
  [242, 139, 55],
  [226, 90, 79],
  [188, 76, 169],
  [135, 91, 219],
  [226, 40, 55],
  [185, 193, 207],
  [246, 248, 252],
]);

const PALETTE_LUT = new Uint8Array(32 * 32 * 32);

for (let red = 0; red < 32; red += 1) {
  for (let green = 0; green < 32; green += 1) {
    for (let blue = 0; blue < 32; blue += 1) {
      const r = red * 255 / 31;
      const g = green * 255 / 31;
      const b = blue * 255 / 31;
      let best = 0;
      let bestDistance = Number.POSITIVE_INFINITY;
      for (let index = 0; index < CASIO_PALETTE.length; index += 1) {
        const [pr, pg, pb] = CASIO_PALETTE[index];
        const dr = r - pr;
        const dg = g - pg;
        const db = b - pb;
        const distance = dr * dr * 0.299 + dg * dg * 0.587 + db * db * 0.114;
        if (distance < bestDistance) {
          bestDistance = distance;
          best = index;
        }
      }
      PALETTE_LUT[(red << 10) | (green << 5) | blue] = best;
    }
  }
}

export function quantizeRgbaToPacked(rgba, width, height) {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0 ||
      (width * height) % 2 || rgba.length !== width * height * 4) {
    throw new RangeError('Dimensiones RGBA inesperadas');
  }
  const packed = new Uint8Array(width * height / 2);
  for (let pixel = 0, output = 0; pixel < width * height; pixel += 2, output += 1) {
    const first = pixel * 4;
    const second = first + 4;
    const left = PALETTE_LUT[((rgba[first] >> 3) << 10) | ((rgba[first + 1] >> 3) << 5) | (rgba[first + 2] >> 3)];
    const right = PALETTE_LUT[((rgba[second] >> 3) << 10) | ((rgba[second + 1] >> 3) << 5) | (rgba[second + 2] >> 3)];
    packed[output] = (left << 4) | right;
  }
  return packed;
}

export function quantizeRgba(rgba) {
  return quantizeRgbaToPacked(rgba, CYT.WIDTH, CYT.HEIGHT);
}

export function renderPackedFrame(canvas, packed) {
  const context = canvas.getContext('2d', { alpha: false });
  canvas.width = 384;
  canvas.height = 216;
  const image = context.createImageData(384, 216);
  const data = image.data;

  for (let y = 0; y < CYT.HEIGHT; y += 1) {
    for (let x = 0; x < CYT.WIDTH; x += 1) {
      const pair = packed[(y * CYT.WIDTH + (x & ~1)) / 2];
      const paletteIndex = x & 1 ? pair & 0x0f : pair >> 4;
      const [red, green, blue] = CASIO_PALETTE[paletteIndex];
      const targetX = x * 3;
      const targetY = y * 3;
      for (let dy = 0; dy < 3; dy += 1) {
        for (let dx = 0; dx < 3; dx += 1) {
          const offset = ((targetY + dy) * 384 + targetX + dx) * 4;
          data[offset] = red;
          data[offset + 1] = green;
          data[offset + 2] = blue;
          data[offset + 3] = 255;
        }
      }
    }
  }
  context.putImageData(image, 0, 0);
}

export class FrameEncoder {
  #previous = null;
  #sequence = 0;
  #framesSinceKey = 0;

  reset() {
    this.#previous = null;
    this.#framesSinceKey = 0;
  }

  forceKeyframe() {
    this.#previous = null;
    this.#framesSinceKey = 0;
  }

  encode(current) {
    if (!(current instanceof Uint8Array) || current.length !== CYT.FRAME_BYTES) {
      throw new RangeError('Frame CasioYT inválido');
    }

    this.#sequence = (this.#sequence + 1) & 0xffff;
    if (this.#sequence === 0) this.#sequence = 1;

    const keyPayload = rleEncode(current);
    let type = CYT.TYPE_KEYFRAME;
    let payload = keyPayload;

    if (this.#previous && this.#framesSinceKey < 31) {
      const delta = new Uint8Array(current.length);
      for (let index = 0; index < current.length; index += 1) delta[index] = current[index] ^ this.#previous[index];
      const deltaPayload = rleEncode(delta);
      if (deltaPayload.length < keyPayload.length) {
        type = CYT.TYPE_DELTA;
        payload = deltaPayload;
      }
    }

    return {
      type,
      sequence: this.#sequence,
      payload,
      packet: packPacket(type, 0, this.#sequence, payload),
      frame: current.slice(),
    };
  }

  commit(encoded) {
    this.#previous = encoded.frame;
    this.#framesSinceKey = encoded.type === CYT.TYPE_KEYFRAME ? 0 : this.#framesSinceKey + 1;
  }
}

export function framesEqual(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  for (let index = 0; index < left.length; index += 1) {
    if (left[index] !== right[index]) return false;
  }
  return true;
}
