import { CYT } from './cytProtocol.js';
import { quantizeRgba } from './frameEncoder.js';

function waitForVideo(video) {
  return new Promise((resolve, reject) => {
    const timer = window.setTimeout(() => reject(new Error('La captura no ha producido imagen')), 5000);
    video.addEventListener('loadedmetadata', () => {
      window.clearTimeout(timer);
      resolve();
    }, { once: true });
  });
}

export async function startPlayerCapture(targetElement) {
  if (!navigator.mediaDevices?.getDisplayMedia) throw new Error('Este navegador no permite compartir una pestaña');
  const stream = await navigator.mediaDevices.getDisplayMedia({
    video: {
      displaySurface: 'browser',
      frameRate: { ideal: 12, max: 15 },
    },
    audio: false,
    preferCurrentTab: true,
    selfBrowserSurface: 'include',
    surfaceSwitching: 'exclude',
  });

  const video = document.createElement('video');
  video.muted = true;
  video.playsInline = true;
  video.srcObject = stream;
  await waitForVideo(video);
  await video.play();

  const track = stream.getVideoTracks()[0];
  let cropped = false;
  if (window.CropTarget?.fromElement && typeof track.cropTo === 'function') {
    try {
      const target = await window.CropTarget.fromElement(targetElement);
      await track.cropTo(target);
      cropped = true;
    } catch {
      cropped = false;
    }
  }

  return {
    stream,
    track,
    video,
    cropped,
    stop() {
      for (const mediaTrack of stream.getTracks()) mediaTrack.stop();
      video.pause();
      video.srcObject = null;
    },
  };
}

export function samplePlayerFrame(capture, targetElement, sampleCanvas) {
  sampleCanvas.width = CYT.WIDTH;
  sampleCanvas.height = CYT.HEIGHT;
  const context = sampleCanvas.getContext('2d', {
    alpha: false,
    colorSpace: 'srgb',
    willReadFrequently: true,
  });
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = 'high';

  if (capture.cropped) {
    context.drawImage(capture.video, 0, 0, capture.video.videoWidth, capture.video.videoHeight, 0, 0, CYT.WIDTH, CYT.HEIGHT);
  } else {
    const rect = targetElement.getBoundingClientRect();
    const viewportWidth = window.visualViewport?.width || window.innerWidth;
    const viewportHeight = window.visualViewport?.height || window.innerHeight;
    const scaleX = capture.video.videoWidth / viewportWidth;
    const scaleY = capture.video.videoHeight / viewportHeight;
    const sourceX = Math.max(0, rect.left * scaleX);
    const sourceY = Math.max(0, rect.top * scaleY);
    const sourceWidth = Math.min(capture.video.videoWidth - sourceX, rect.width * scaleX);
    const sourceHeight = Math.min(capture.video.videoHeight - sourceY, rect.height * scaleY);
    context.drawImage(capture.video, sourceX, sourceY, sourceWidth, sourceHeight, 0, 0, CYT.WIDTH, CYT.HEIGHT);
  }

  return quantizeRgba(context.getImageData(0, 0, CYT.WIDTH, CYT.HEIGHT).data);
}
