export const CYT = Object.freeze({
  VERSION: 1,
  HEADER_SIZE: 16,
  MAX_PAYLOAD: 5200,
  WIDTH: 128,
  HEIGHT: 72,
  FRAME_BYTES: 128 * 72 / 2,
  TYPE_KEYFRAME: 1,
  TYPE_DELTA: 2,
  TYPE_CONTROL: 3,
  TYPE_STATUS: 4,
  TYPE_CATALOG: 5,
  CONTROL_TEST: 1,
  CONTROL_KEYS: 2,
  CONTROL_STOP: 3,
  CONTROL_PING: 4,
  CONTROL_KEYFRAME: 5,
  CONTROL_SEARCH: 6,
  CONTROL_SELECT: 7,
  CONTROL_BACK: 8,
  CONTROL_BRIDGE: 9,
  CATALOG_RESET: 1,
  CATALOG_ITEM: 2,
  CATALOG_DONE: 3,
  CATALOG_ERROR: 4,
  SEARCH_RESULTS: 5,
  SEARCH_MAX: 72,
  TITLE_MAX: 56,
  CHANNEL_MAX: 32,
  VIDEO_ID_SIZE: 11,
  THUMB_WIDTH: 80,
  THUMB_HEIGHT: 45,
  THUMB_BYTES: 80 * 45 / 2,
  STATUS_READY: 1,
  STATUS_ACK: 2,
  STATUS_STOPPED: 3,
  STATUS_BUSY: 4,
  STATUS_BAD_FRAME: 5,
});

const MAGIC = new Uint8Array([0x43, 0x59, 0x54, 0x31]);
const CRC_TABLE = new Uint32Array(256);

for (let index = 0; index < CRC_TABLE.length; index += 1) {
  let value = index;
  for (let bit = 0; bit < 8; bit += 1) {
    value = (value >>> 1) ^ ((-(value & 1)) & 0xedb88320);
  }
  CRC_TABLE[index] = value >>> 0;
}

function crcContinue(crc, bytes, start, end) {
  let value = crc >>> 0;
  for (let index = start; index < end; index += 1) {
    value = (value >>> 8) ^ CRC_TABLE[(value ^ bytes[index]) & 0xff];
  }
  return value >>> 0;
}

export function packetCrc(packet, payloadLength = packet.length - CYT.HEADER_SIZE) {
  let crc = crcContinue(0xffffffff, packet, 0, 12);
  crc = crcContinue(crc, packet, CYT.HEADER_SIZE, CYT.HEADER_SIZE + payloadLength);
  return (~crc) >>> 0;
}

export function packPacket(type, flags, sequence, payload = new Uint8Array()) {
  if (!(payload instanceof Uint8Array)) payload = new Uint8Array(payload);
  if (payload.length > CYT.MAX_PAYLOAD) throw new RangeError('Payload CasioYT demasiado grande');

  const packet = new Uint8Array(CYT.HEADER_SIZE + payload.length);
  packet.set(MAGIC, 0);
  packet[4] = CYT.VERSION;
  packet[5] = type;
  packet[6] = flags;
  packet[7] = 0;
  const view = new DataView(packet.buffer);
  view.setUint16(8, sequence & 0xffff, true);
  view.setUint16(10, payload.length, true);
  packet.set(payload, CYT.HEADER_SIZE);
  view.setUint32(12, packetCrc(packet, payload.length), true);
  return packet;
}

export function unpackPacket(packet) {
  if (!(packet instanceof Uint8Array) || packet.length < CYT.HEADER_SIZE) return null;
  for (let index = 0; index < MAGIC.length; index += 1) {
    if (packet[index] !== MAGIC[index]) return null;
  }
  if (packet[4] !== CYT.VERSION || packet[7] !== 0) return null;
  const view = new DataView(packet.buffer, packet.byteOffset, packet.byteLength);
  const payloadLength = view.getUint16(10, true);
  if (payloadLength > CYT.MAX_PAYLOAD || packet.length !== CYT.HEADER_SIZE + payloadLength) return null;
  if (view.getUint32(12, true) !== packetCrc(packet, payloadLength)) return null;
  return {
    type: packet[5],
    flags: packet[6],
    sequence: view.getUint16(8, true),
    payload: packet.slice(CYT.HEADER_SIZE),
    raw: packet,
  };
}

function findMagic(bytes) {
  outer: for (let index = 0; index <= bytes.length - MAGIC.length; index += 1) {
    for (let offset = 0; offset < MAGIC.length; offset += 1) {
      if (bytes[index + offset] !== MAGIC[offset]) continue outer;
    }
    return index;
  }
  return -1;
}

function concat(left, right) {
  const merged = new Uint8Array(left.length + right.length);
  merged.set(left);
  merged.set(right, left.length);
  return merged;
}

export class CytParser {
  #buffer = new Uint8Array();

  reset() {
    this.#buffer = new Uint8Array();
  }

  feed(chunk) {
    this.#buffer = concat(this.#buffer, chunk);
    const packets = [];

    while (this.#buffer.length >= MAGIC.length) {
      const start = findMagic(this.#buffer);
      if (start < 0) {
        this.#buffer = this.#buffer.slice(Math.max(0, this.#buffer.length - 3));
        break;
      }
      if (start > 0) this.#buffer = this.#buffer.slice(start);
      if (this.#buffer.length < CYT.HEADER_SIZE) break;

      const view = new DataView(this.#buffer.buffer, this.#buffer.byteOffset, this.#buffer.byteLength);
      const payloadLength = view.getUint16(10, true);
      if (this.#buffer[4] !== CYT.VERSION || this.#buffer[7] !== 0 || payloadLength > CYT.MAX_PAYLOAD) {
        this.#buffer = this.#buffer.slice(1);
        continue;
      }

      const total = CYT.HEADER_SIZE + payloadLength;
      if (this.#buffer.length < total) break;
      const candidate = this.#buffer.slice(0, total);
      const packet = unpackPacket(candidate);
      this.#buffer = this.#buffer.slice(packet ? total : 1);
      if (packet) packets.push(packet);
    }
    return packets;
  }
}

export function rleEncode(source) {
  const output = new Uint8Array(source.length + Math.ceil(source.length / 128) + 16);
  let input = 0;
  let used = 0;

  while (input < source.length) {
    let run = 1;
    while (input + run < source.length && source[input + run] === source[input] && run < 128) run += 1;

    if (run >= 3) {
      output[used++] = 0x80 | (run - 1);
      output[used++] = source[input];
      input += run;
      continue;
    }

    const literalStart = input;
    let count = 0;
    while (input < source.length && count < 128) {
      run = 1;
      while (input + run < source.length && source[input + run] === source[input] && run < 128) run += 1;
      if (count > 0 && run >= 3) break;
      if (run >= 3) break;
      let take = Math.min(run, 128 - count);
      count += take;
      input += take;
    }
    if (!count) throw new Error('No se pudo codificar el frame');
    output[used++] = count - 1;
    output.set(source.subarray(literalStart, literalStart + count), used);
    used += count;
  }
  return output.slice(0, used);
}

export function rleApply(frame, encoded, xorDelta = false) {
  let input = 0;
  let output = 0;
  while (input < encoded.length) {
    const code = encoded[input++];
    const count = (code & 0x7f) + 1;
    if (count > frame.length - output) return false;
    if (code & 0x80) {
      if (input >= encoded.length) return false;
      const value = encoded[input++];
      for (let index = 0; index < count; index += 1, output += 1) {
        frame[output] = xorDelta ? frame[output] ^ value : value;
      }
    } else {
      if (count > encoded.length - input) return false;
      for (let index = 0; index < count; index += 1, output += 1, input += 1) {
        frame[output] = xorDelta ? frame[output] ^ encoded[input] : encoded[input];
      }
    }
  }
  return output === frame.length;
}

export function fnv1a(bytes) {
  let value = 2166136261;
  for (const byte of bytes) {
    value = Math.imul(value ^ byte, 16777619) >>> 0;
  }
  return value >>> 0;
}

export function packWireCommand(payload) {
  const encoder = new TextEncoder();
  const body = encoder.encode(payload);
  const checksum = fnv1a(body).toString(16).toUpperCase().padStart(8, '0');
  return encoder.encode(`\n@@@${payload}*${checksum}\n`);
}

export function parseWireLine(line) {
  const marker = line.indexOf('@@@');
  if (marker < 0) return null;
  const framed = line.slice(marker + 3).trim();
  const separator = framed.lastIndexOf('*');
  if (separator < 0) return null;
  const payload = framed.slice(0, separator);
  const expected = Number.parseInt(framed.slice(separator + 1), 16);
  if (!Number.isFinite(expected) || fnv1a(new TextEncoder().encode(payload)) !== expected) return null;
  return payload;
}
